select *, sum(discount) over (partition by customer_id, status order by order_date, id rows between unbounded preceding and current row) as running_discount, avg(discount) over (order by amount, id rows between 3 preceding and current row) as discount_avg_3, ntile(4) over (partition by status, store_id order by discount desc, id) as discount_bucket, count(amount) over (partition by customer_id) as customer_id_count_amount, lag(amount, 1) over (order by discount, id) as prev_amount from orders;
